import sympy

def break_into_primes_greedy(s):
    primes = []
    end = len(s)

    while end > 0:
        found = False
        for start in range(end):
            num = int(s[start:end])
            if sympy.isprime(num):
                primes.insert(0, num)
                end = start
                found = True
                break

        # If no prime is found, we can't break the string into primes
        if not found:
            raise ValueError("Couldn't break string into primes.")

    return primes

